class Solution {
    public:long long maxProfit(vector<int>& workers,vector<vector<int>>& tasks) {
        unordered_map<int,int> capacity;
        for(int w:workers)capacity[w]++;
        unordered_map<int,vector<int>> profit;
        for(auto &t:tasks)profit[t[0]].push_back(t[1]);
        long long base=0;
        int extra=0;
        for(auto &entry:profit) {
            auto &v=entry.second;
            sort(v.begin(),v.end(),greater<int>());
            int cnt=min((int)v.size(),capacity[entry.first]);
            for(int i=0; i<cnt; i++)base+=v[i];
            if(cnt<(int)v.size())extra=max(extra,v[cnt]);
            else if(cnt>0)extra=max(extra,0);
        }
        return base+extra;
    }
}
